"""Deterministic candidate source assembly; never a gameplay run, listening asset or human approval."""
from pathlib import Path
import json, hashlib, re

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
VERSION="r4-author-candidate-1"
MATERIALS=[]
SOURCES=["docs/baseline/World_Story_Bible_v0.1.md:502-549", "docs/baseline/Exploration_Level_Design_v0.1.md:459-494", "docs/baseline/Puzzle_System_v0.1.md:475-514", "docs/baseline/English_Learning_System_v0.1.md:794-797"]
def material(mid,title,q,kind,spot,source,pairs,details=(),access="public"):
    paragraphs=[dict(id=f"{mid}-p{i:02}",en=en.strip(),zh=zh.strip()) for i,(en,zh) in enumerate(pairs,1)]
    count=sum(len(re.findall(r"[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)*",p["en"])) for p in paragraphs)
    item=dict(id=mid,content_version=VERSION,translation_version=VERSION+"-zh",title_zh=title,quest_ref=q,kind=kind,location=dict(scene=spot.split('.')[0],spot=spot),source_root=source,access_class=access,review_status="original_unreviewed",human_review="human_pending",target_band=6.5,calibration_status="human_pending_not_a_score",rights_status="original_text_candidate_human_pending",original_local_details=list(details),source_refs=SOURCES,paragraphs=paragraphs,english_word_count=count,audio_asset="")
    if kind=="listening_script":item.update(audio_status="not_recorded",actual_duration_seconds=None,voice_performer="human_pending",performance_and_voice_rights="human_pending",planned_rate_wpm=[140,175],estimated_duration_seconds_range=[round(count*60/175),round(count*60/140)],duration_status="word_count_estimate_not_measured_audio",listening_experience_status="script_only")
    MATERIALS.append(item);return item

material("R4-Q401-R-LANDING","学城样本接收台","Q-401","short_notice","R4-S01.reception","r4-sample-receiving-desk",[
("Bring the sealed MC-2 sample and the mine's actual handover receipt to this desk. We will check the seal, batch, source versions and receiving purpose before registering custody. The sample has travelled; a voyage record does not establish its contents or a technical result. The original mine sheets remain with their custodians. Their references accompany the sample, and a copy retains its original source root.","请把密封MC-2样本和矿区实际移交回执带到此台。登记保管前，核对封签、批次、来源版本和接收用途。样本已运来，航行记录却不证明样本内容或技术结论。矿区原件留在原保管处，索引随样本交接，副本保留原来源根。"),
("Sian Lune will define the public verification work in the courtyard. Safe return registration belongs to the landing desk. Neither a sample deposit nor an invitation to discuss findings gives authority to start an old experimental machine, enter a protected personal record, or publish an identity.","西安·卢恩会在中庭说明公共核验工作。安全返程在登陆台登记。交样本或接受讨论邀请，都没有授予启动旧实验机、查阅受保护私人记录或发布身份的权限。")],["R3-MC2-SAMPLE-01 continues exact Q304 seal; deposit checks no invented sample contents"])
material("R4-Q401-R-BRIEF","西安：相同的核验要求","Q-401","mission_document","R4-S02.sian","r4-sian-public-verification-brief",[
("Sian's brief asks you to compare observations before proposing an explanation. The mine has documented dangerous changes and a high extraction setting. Those observations matter, but an association does not alone identify the mechanism or establish that a replacement control scheme is safe. The same requirement applies to the Lamp Authority and to visitors who favour local control. Personal trust in a designer cannot replace the missing checks.","西安要求先比较观察，再提出解释。矿区记录了危险变化及高抽取设置，这些观察有意义，但关联不能单独识别机制，也不能证明替代控制方案安全。灯署和支持本地控制的访客遵循同一要求。对设计者的私人信任不能替代缺少的检查。"),
("Two independent survey teams kept separate field records during the stated comparison window. Read their locations, load bands, instruments and limitations. A report copied from a field sheet is useful for checking publication; it does not add another observer. The public table keeps measurements in local indicator units, so you need no outside electrical calculation. Compare like conditions where the records permit it, and state what remains uncontrolled.","两支独立调查队在注明比较窗口各留现场记录。请读地点、负荷档、仪表与限制。由现场页抄成的报告有助于查发行过程，没有增加一名观察者。公开表使用本地指标单位，无需外部电气计算。材料允许时比较相近条件，注明尚未控制的变量。"),
("The records custodian can grant a bounded review of the retained manuscript, issued report and circulation register. Access depends on the purpose and necessary fields, not on agreeing with a political position. Keep any unfavourable result. The old trial hall is a separate physical assignment. You may pursue that work while preparing your data overview; the small island trial will require both work streams.","记录保管人可按范围开放留存原稿、发行稿及流转册。访问取决于用途和必要字段，不取决于政治观点。应保留不利结果。旧试验厅是另一项实体工作，可在准备数据概览时并行推进；小规模孤网试验需要两边完成。")])
material("R4-Q401-R-SURVEY-A","独立调查A：地点与抽取档","Q-401","mission_document","R4-S03.survey_a","r4-survey-team-a-field-original",[
("Survey team A used indicator IA-4 at the harbour and the mine during window W-1. The harbour station was in its declared lower-load band, with a local load reading of 40 and indicator reading 2. The mine station was in its higher-load band, with local load 70 and indicator reading 7. The instrument sheets retain their sampling window and location plates. Indicator readings describe the declared risk marker, not a forecast of an individual person's safety.","调查A队在W-1窗口使用IA-4记录港口与矿区。港口处于声明的较低负荷档，本地负荷40、指标2；矿区处于较高负荷档，负荷70、指标7。仪表页保留窗口和地点标牌。指标反映声明的风险标志，不预测某个人是否安全。"),
("This comparison changes location as well as load. Ground conditions, prior use and supply connections differ. The curve is a reason to test a hypothesis about load and damage, not a controlled proof that one number explains every difference. The apparatus units used later in Controller A trials are a separate scale; matching the printed number 40 does not make a field station and a laboratory controller the same object.","这一比较同时改变地点与负荷，地层、既往使用和供给连接均有差异。曲线可提出负荷与损伤的待检假设，不能证明一个数字解释所有差异。后来A控制器的试验单位是另一尺度；同样印着40，不表示现场站与实验控制器是同一对象。"),
("The original observation remained unchanged when the public report was prepared. To check whether an unfavourable entry was omitted, compare its identifier and publication version with the retained manuscript and issue register. The later report is a presentation of this source. It does not become an independent survey because another office copied it.","形成公开报告时，原观察没有改写。查是否漏去不利条目，应比条目标识、留存原稿和发行册版本。后报告是此来源的呈现，不因另一办公室抄写而成为独立调查。")],["W1/IA4 and 40→2,70→7 field data are original local candidate units, not ControllerA laboratory scale"])
material("R4-Q401-R-SURVEY-B","独立调查B：复核与地点限制","Q-401","mission_document","R4-S03.survey_b","r4-survey-team-b-field-original",[
("Team B took its own readings with instrument IB-2 during W-1. At the priory's lower-load station it recorded local load 40 and indicator 3. At the mine's higher-load station it recorded local load 70 and indicator 8. The mine readings come from a second field visit and instrument; they are not a transcription of team A. Keep that independence distinct from agreement between the two numbers.","B队在W-1窗口以IB-2独立记录。修院较低档为本地负荷40、指标3；矿区较高档为70、指标8。矿区记录来自另一次现场访问与仪表，不是A队抄录。来源独立与两个数字相近是不同事项。"),
("Both teams observed a higher indicator at the mine than at their lower-load comparison station. They did not hold every location condition constant, and their indicator scales share a declared reference rather than identical precision. The dataset supports a testable association. The controlled trial must examine the proposed mechanism and preserve a result that might contradict the proposed replacement scheme.","两队均观察到矿区指标高于各自低负荷比较站。它们没有固定所有地点条件，指标尺度使用声明参考而非完全相同精度。数据支持可检验关联。受控试验还须检验拟议机制，并保留可能反驳替代方案的结果。"),
("A second instrument does not give access to information outside its recorded window. These sheets do not identify Mara's current condition, every person responsible for a network decision, or an approved permanent operating limit. Questions about those matters require the appropriate records and their own review.","第二台仪表不会提供记录窗口以外的信息。这些页没有确定玛拉当前情况、每位网络决策责任人，也没有批准永久运行上限。这些问题需相应记录另行核验。")],["IB2 independent survey; 40→3/70→8; W1 candidate common window"])
material("R4-Q401-R-VISUAL","四行观测概览","Q-401","short_notice","R4-S03.table","r4-comparison-table-from-a-and-b",[
("The table has four field entries: team A harbour, 40 / 2; team A mine, 70 / 7; team B priory, 40 / 3; team B mine, 70 / 8. The first number is each station's local load reading; the second is its declared risk indicator. Keep team, location and window W-1 in the description. The four entries are not four repeated runs of Controller A.","表有四行：A队港口40/2、A队矿区70/7、B队修院40/3、B队矿区70/8。第一数为各站本地负荷，第二数为声明的风险指标。说明应保留团队、地点和W-1窗口，四行不是A控制器四次重复试验。"),
("The comparison preserves the source references rather than creating a fifth observation. Describe the broad pattern and important limits, then propose a check that could distinguish explanations. A careful overview may say that the evidence is incomplete. It should not turn that uncertainty into either a guarantee of a replacement scheme or a rejection of every possible local arrangement.","表保留来源索引，没有增加第五次观察。请说明大体模式、关键限制，并提出可区分解释的核验。不完整的证据可以如实写出，不能把不确定性改成替代方案保证，也不能据此排除所有本地安排。")])
material("R4-Q401-R-ACCESS","保管人限定调阅条款","Q-401","short_notice","R4-S03.custodian","r4-custodian-review-terms",[
("For public-data verification, the custodian permits review of report GH-R7 version 7, including observation identifiers, tested conditions, outcome entries, the issue version and circulation dates. Ask for those necessary fields and state the receiving technician and purpose. Political agreement is not an access condition. Household addresses, personal correspondence and unrelated medical fields remain outside this permission.","公共数据核验可调阅GH-R7报告第7版，范围包括观察标识、受试条件、结果、发行版本与流转日期。应申请必要字段，说明接收技术员和用途。政治赞同不是调阅条件。住址、私人通信和无关医疗字段不在许可内。"),
("Compare retained and issued copies only when the register shows that they belong to the same reporting version. A normal update at another date is not automatically a deletion. A reading permission allows this inspection and a bounded factual finding; it is not a general licence to publish protected identities.","只有流转册说明留存与发行件属于同一报告版本，才比较删改。另一日期的正常更新不自动成为删除。阅读许可允许本次检查及有限事实核查，没有授予公开受保护身份的一般权限。")])
material("R4-Q401-R-MANUSCRIPT","GH-R7-v7留存原稿","Q-401","short_notice","R4-S04.manuscript","r4-ghr7-retained-manuscript",[
("Retained manuscript GH-R7, reporting version 7: the outcome appendix lists T1 stable, T2 stopped, T3 stopped and T4 stable. Each entry names Controller A, ten minutes, isolation checked, load and reserve condition. The four entries are retained as favourable and unfavourable observations. The manuscript's cover identifies the intended issue as reporting version 7.","留存原稿GH-R7、报告第7版：结果附录列T1稳定、T2停止、T3停止、T4稳定，各注明A控制器、十分钟、已隔离、负荷和储备条件。正反观察四项均保留，封面把拟发行件标为报告第7版。"),
("This retained copy is the publication chain's original record of the appendix. It does not replace a physical reconstruction in the trial hall. It cannot establish that an untested load is safe, or that stopping excess extraction makes the pre-existing mist disappear immediately.","这份留存件是发行链中附录的原始记录，不能代替试验厅实体复原。它没有证明未测负荷安全，也没有证明停止超额抽取可令原本存在的雾立即消失。")],access="controlled_review")
material("R4-Q401-R-ISSUED","GH-R7-v7发行稿","Q-401","short_notice","R4-S04.issued","r4-ghr7-retained-manuscript",[
("Issued report GH-R7, reporting version 7: the displayed appendix contains T1 stable and T4 stable. The outcome rows for T2 and T3 are absent. The issued cover carries the same reporting-version identifier as the retained manuscript. Compare the actual appendix and circulation record; do not rely on a title alone.","发行报告GH-R7、报告第7版：所示附录只有T1稳定、T4稳定，T2、T3结果行缺失。发行封面与留存原稿使用同一报告版本标识。应比较实际附录与流转册，不能仅依标题。"),
("The two displayed stable runs repeat the same listed configuration. Their repetition does not justify the missing failure rows, prove load 55, or approve permanent six-tower use. The issued report shares the manuscript's source chain. Two saved copies of this issue do not provide two independent controlled trials.","所示两次稳定记录重复同样配置。重复没有解释缺失失败行，没有证明55负荷，也没有批准六塔永久使用。发行稿属于原稿来源链，两份已保存发行件不会变成两次独立受控试验。")],access="controlled_review")
material("R4-Q401-R-CIRCULATION","第7版流转记录","Q-401","short_notice","R4-S04.circulation","r4-ghr7-version-custody-register",[
("The circulation register pairs retained manuscript GH-R7-v7 with issued copy GH-R7-v7 in the same issue packet. Its checked field records the appendix change: outcome rows T2 and T3 removed before issue; reporting-version number unchanged. This is a specific difference within a paired version, not a comparison of unrelated dates. Preserve both documents and this register.","流转册把GH-R7-v7留存原稿与GH-R7-v7发行稿列于同一发行包。核对字段记附录变化：发行前删除T2、T3结果行，报告版本号未改。这是同版成对文档的特定差异，不是任意比较两个日期。两件与此册均应保留。"),
("The register establishes what changed in presentation and when it entered this packet. It does not by itself identify every authorising official or validate a replacement scheme. Later supervised field work cannot rewrite this earlier publication difference. Wider responsibility will need additional original records.","册证明此包呈现内容怎样改变以及何时进入，单凭此册尚未识别全部授权人，也未验证替代方案。后来有监督的现场工作不能改写早先发行差异，较广责任需更多原始记录。")],["GH-R7-v7 same-version retained/issued aliases; deletion rows T2/T3; no premature E09 release"],access="controlled_review")
material("R4-Q401-L-SIAN","西安的研究简报脚本","Q-401","listening_script","R4-S02.briefing","r4-sian-briefing-original",[
("Sian: Start with what the sheets actually record. Two teams made field visits; a report office copied selected rows. Those are different kinds of source. A curve can guide a question without settling it. I will apply the same test to a claim made by the Authority and to a claim made by you. Please name a condition that your explanation has not yet controlled.","西安：从纸页实际记录出发。两队做现场访问，报告办公室选抄部分行，两者是不同来源。曲线可以引导问题，无需先定结论。灯署的主张和你的主张遵循同一核验。请列你解释尚未控制的一项条件。"),
("The custodian will check the requested fields rather than your political preference. Keep the manuscript and the issued copy together. We also need to see the old apparatus fail under its recorded condition. A stopped machine is an observation, not a reason to discard the room as useless. The safer alternative still has to work within a stated load, reserve and duty arrangement.","保管人检查所申请字段，不检查政治偏好。原稿与发行稿一起保存，还须看旧装置按记录条件失败。机器停止是一项观察，不能据此把房间标为无用。较安全的替代方案仍须在注明的负荷、储备和岗位安排中工作。")])
material("R4-Q402-R-SAFETY","旧试验厅的隔离与复原许可","Q-402","mission_document","R4-S02.safety_desk","r4-old-hall-safety-permit-terms",[
("The old hall permit covers the external isolation switch, debris enclosure, reserve service segment and the fixed Controller A test bench. Keep the public return corridor usable. The debris and reserve segment have separate control records; resolving one does not resolve the other. Visitors receive access to the installed local trial fixture. Its parts are not an award of enhanced equipment for the six towers.","旧厅许可包括外侧隔离开关、残件围护、储备服务段和固定A控制器试验台。应保留公共返程走廊。残件和备用段分别登记处置，完成一项不会完成另一项。访客使用已装的本地试验器材，不等于领取六塔增强设备。"),
("Inspect the external dead circuit before opening the old case. The debris enclosure must be controlled through the actual encounter. For the reserve segment, either use the isolated manual service procedure—open, clear, secure and inspect—or control its separate maintenance threat. The physical result must be recorded before the connection is checked. Read instructions from the protected work stand; no action requires a rare talent or a particular companion.","打开旧外壳前，从外侧检查断路。残件围护须实际遭遇制止。备用段可以用隔离手动步骤：打开、清理、固定、检查；也可处理其独立维护威胁。核对连接前须记录物理结果。在安全工作站读说明，无需稀有天赋或特定同伴。"),
("The bench stops safely when its recorded failure condition is reached. It does not destroy a main-line component. Save the failed run and the configuration before resetting the local apparatus. A reset removes local preparation and current tests; it preserves sources, historical runs, the sample deposit and other districts' progress. No waiting in real time is required: the inspection controls advance the declared simulation clock.","试验台达到记录的失败条件时安全停止，不毁主线部件。局部复位前，保存失败运行与配置。复位清当前准备和测试，保留来源、历史运行、样本交接及外区进展。无需实时等待，由检查操作推进声明的模拟时钟。")],["Manual reserve procedure local candidate, alternative ENC-R4-02; simulation clock not real-time timer"])
material("R4-Q402-R-RECONSTRUCT","A控制器失败配置卡","Q-402","mission_document","R4-S05.bench","r4-controller-a-original-configuration",[
("Controller A is installed in the old hall. Check isolation, secure its external guard and inspect the labelled reserve socket before changing a load. The failure reconstruction uses the recorded T2 condition: load 70, reserve connected, ten minutes. Confirm the apparatus plate as A. This trial scale is the apparatus's own scale; do not calculate a town's supply from it or replace the record with a different controller.","A控制器装在旧厅。改负荷前检查隔离、固定外护罩并查看储备插座标记。失败复原使用T2条件：负荷70、连接储备、十分钟；确认装置标牌为A。单位属于此台，不能据此计算城镇供给，也不能换另一控制器冒充同记录。"),
("Advance the inspection clock through two five-minute observations. The final safe stop belongs to the configured run, not to the observer's preference. Record the result and all listed conditions. A written prediction or a saved configuration has not executed the run. If you choose the T3 condition—load 40 with no reserve—the preserved record predicts a different failed configuration. It addresses reserve availability, rather than the single load comparison.","通过两次五分钟观察推进检查时钟。末次安全停止由配置决定，不随观察者偏好改变。记录结果及所列条件；写预测、存配置都没有执行运行。若选T3条件：40且无储备，保留页预测另一个失败配置，讨论的是储备而非单独负荷比较。"),
("The old controller remains available for a later bounded positive check. Keeping a failed result does not force you to reject every local-control arrangement. Conversely, a later stable result cannot delete T2 or T3. Before a broader trial, carry the retained conditions to the calibration room and check its own isolation, reserve and instruments. Old settings do not certify that new configuration.","旧控制器仍可供后来有限正例核验。保留失败结果不强迫你排除所有本地控制，后来稳定也不能删除T2或T3。较广试验前，携条件到校准间，检查该处隔离、储备与仪表；旧设置不会认证新配置。")])
original=json.loads((ROOT/"content/source/part06-Puzzle_Materials_v0.1.json").read_text(encoding="utf-8"))["materials"]
protocol=next(m for m in original if m["id"]=="PZLAB-R-PROTOCOL")
translations=["这些是A控制器的短时本地试验。每次十分钟，隔离已检查。负荷用台内单位，无需外部工程计算。稳定表示这十分钟符合声明条件，不代表批准任何塔或永久运行。","T1负荷40、接储备，稳定；T2负荷70、接储备，停止；T3负荷40、无储备，停止；T4重复T1，稳定。没有测试55，也没有六塔全规模运行。","比较负荷变化且保持所列配置相同，可比T1/T2。T1/T3讨论另一种变化。报告说明实际观察条件，未测组合保持开放；较广方案还须更多试验与现场检查。"]
item=material("PZLAB-R-PROTOCOL",protocol["title"],"Q-402","mission_document","R4-S05.protocol","pzlab-controller-a-original",[(p["text"],z) for p,z in zip(protocol["paragraphs"],translations)])
item["content_version"]="0.1";item["originality"]="immutable_upstream_english_with_new_unreviewed_chinese";item["paragraphs"]=[dict(id=p["id"],en=p["text"],zh=z) for p,z in zip(protocol["paragraphs"],translations)];item["upstream_sha256"]=hashlib.sha256((ROOT/"content/source/part06-Puzzle_Materials_v0.1.json").read_bytes()).hexdigest()
material("R4-Q402-R-CALIBRATION","校准间器材与读数检查","Q-402","mission_document","R4-S06.calibration","r4-calibration-room-instrument-protocol",[
("The calibration room contains the installed island-trial controller C, a local reserve module and two labelled channels. Channel Z is the zero reference; channel R is the fixed reference mark. Check Z at 0 and R at 10 before recording a calibration. These are local instrument marks, not tower operating units. Both checks must belong to the current instrument revision. Changing the channel connection or bypassing its isolation invalidates the previous check.","校准间已装孤网控制器C、本地储备模块和两标记通道。Z为零参考，R为固定参考标。记录校准前，Z应为0、R应为10；它们是本地仪表标记，不是塔运行单位。两检查都应属于当前仪表版本，改连接或绕隔离令旧检查失效。"),
("Before the live island arrangement, control the calibration defence from the external stand, inspect the isolation, seat the labelled reserve connector and secure both guards. The checked reserve is the room's installed reserve, not the Glimmer's battery. Declare a local duty officer and a review officer for the bounded current window. These are trial posts only; they do not occupy or grant permanent six-tower operator posts.","带载孤网准备前，从外侧站位制止校准防卫，检查隔离、座好带标储备连接头并固定护罩。受检储备属于此室，不是微光号电池。为当前有限窗口明确试验操作员与复核员；这些是试验岗位，没有占用或授予六塔永久岗位。"),
("The trial field may be entered once both prior reports and this current preparation are ready. You will still need to inspect the field's output route and control its execution machine. A calibration receipt proves the present measuring setup; it does not prove that the unexecuted ten-minute trial will succeed, that an untested load is safe, or that another district is prepared.","两份前报告及当前准备成立后可进入试验场，仍须检查输出通路并制止执行机。校准回执证明当前测量设置，不证明尚未执行的十分钟试验会成功、未测负荷安全或外区已准备。")],["C,Z0/R10 and current-window two trial posts original bounded local candidate"])
material("R4-Q402-L-TECHNICIAN","失败试验复原员脚本","Q-402","listening_script","R4-S05.technician","r4-old-hall-technician-firsthand",[
("Technician: The controller is isolated at the outer switch. Do not take a silent machine as evidence that its reserve socket is connected. We kept the socket plate and guard inspection separate. Please control the debris enclosure, then use the manual reserve procedure or the separate maintenance encounter. I will keep the return corridor clear while you inspect.","技术员：控制器在外开关隔离。机器安静不证明储备插座已接，我们分别留插座标记和护罩检查。先制止残件，再用备用段手动步骤或独立维护遭遇，我会在检查时保留返程走廊。"),
("You can reconstruct the high-load stop without losing the installed fixture. At five minutes take the first observation, then take the second at ten. Record the configured condition as well as the final outcome. Resetting afterwards leaves that failed run in the archive. A positive run later may support another condition; it cannot make the earlier stop cease to have occurred.","可以复原高负荷停止而不丢已装器材。五分钟取第一观察，十分钟取第二次。记录配置与末次结果。后来复位仍把失败运行留档；之后正例可支持另一条件，不能令早停止从历史消失。")])
material("R4-Q403-R-ISLAND","有限孤网试验规程","Q-403","mission_document","R4-S06.island_protocol","r4-controller-c-island-protocol",[
("Controller C will run a small local circuit at load 40 with the installed reserve connected, local isolation checked and limited contact enabled. The two current trial posts must be assigned and the reference channels checked. The execution machine must be controlled and its output connected to the labelled test route. A battle result establishes the device's safety; it is not a trial observation. Saving this configuration is a preparation step.","C控制器将在40负荷、已接本地储备、已查隔离及有限联络下运行小回路。应安排两个当前试验岗位，检查参考通道，制止执行机并把输出接到标记测试通路。战斗结果证明设备安全，不是试验观察。保存此配置属于准备。"),
("Start from the field console and inspect at minute 5 and minute 10 of the declared simulation clock. Under this recorded configuration the local output meets the declared criterion at both observations. The finite result supports this controller, load, reserve, contact and duty arrangement for this window. Keep a process diagram showing preparation, execution, observation and acceptance as different stages. There is no reading race or real-time countdown.","从场内控制台启动，在声明的模拟钟第5与第10分钟检查。此记录配置下，本地输出两次符合准则。有限结果支持该控制器、负荷、储备、联络与岗位在此窗口的安排。流程图把准备、执行、观察和接受分开，没有阅读竞速或实时倒计时。"),
("You may deliberately inspect the high-load or missing-reserve variants to retain counterexamples. Load 70, reserve absent, isolation bypassed or missing duty causes a safe stop under the authored finite rule. Load 55 is not in this protocol's validated set; the console will refuse to invent a result. Changing configuration expires the current acceptance. Historical successful and failed runs remain available after a local reset.","可以主动检查高负荷或缺储备变体，保留反例。70负荷、缺储备、绕隔离或缺岗位均按作者有限规则安全停止。55不在此规程的已验证集合，控制台拒绝编造结果。改配置使当前接受过期，局部复位保留历史成功与失败。")],["Controller C bounded run rule is original candidate; T1..T4 unchanged; no invented55 inference"])
material("R4-Q403-R-OUTPUT","执行机与测试输出通路","Q-403","mission_document","R4-S07.output","r4-execution-machine-test-route-plate",[
("The execution machine has a labelled output socket and two route selectors. Route TEST returns through the isolated local measuring loop. Route NETWORK would join an unchecked wider line and is outside this permit. Inspect the sockets from the protected stand before control. After the machine is controlled, isolate its output, seat the installed coupler in TEST, secure the guard and inspect the present route. A selected label without these actions is not a connection.","执行机有带标输出插座和两通路选择。TEST经过隔离本地测量环；NETWORK接未经检查的广泛线路，超出许可。制止前从安全站查插座。制止后隔离输出，把已装耦合件座入TEST，固定护罩并核查当前通路。只选择标记不是连接。"),
("The machine's safety record and the experiment's output record have separate owners. Record this route revision before starting the controller. Changing a route later invalidates the current test, and a failed test does not erase the earlier machine control. When the declared observations are saved, open the field's logistics latch from the inside. It adds a return loop to the courtyard while leaving the calibration route usable.","机械安全与实验输出分别记录。启动前记录通路版本，后来改通路使当前测试失效；失败测试不删除早机械制止。声明观察保存后，从内侧打开后勤门，增加回中庭环路，校准通路仍可用。"),
("The retained outputs do not establish safe permanent service for six towers. Each tower still needs its actual base changes, transition supply, common protocol and field trial. Moving a coupler at this installed laboratory fixture does not deliver one to a regional work order or grant that district's representative consent.","保留输出不证明六塔永久安全供给。各塔仍需实际基础改造、过渡供给、共同协议及现场试运行。移动此实验器材上的耦合件，不会向地区工作单交付一件，也不会取得代表同意。")])
material("R4-Q403-L-OBSERVER","两次观察与流程图脚本","Q-403","listening_script","R4-S07.observer","r4-island-review-officer-firsthand",[
("Review officer: I have the present configuration sheet, not a promise of its outcome. The operator starts Controller C only when the execution output has its current TEST route check. At minute five, we retain an intermediate observation. At minute ten, we retain the final result. The controller clock advances when you take those declared observations; the reader does not have to hurry.","复核员：我持当前配置页，不是结果承诺。执行机输出取得当前TEST检查后，操作员才启动C。第5分钟留中间观察，第10分钟留末次结果。取声明观察时控制器钟才推进，阅读者不用赶。"),
("Please draw the process with calibration before entry, physical output preparation before execution, and observations before acceptance. If the configuration changes, we check it again. We keep previous runs as previous runs. A safe stop is a recorded failure in that condition, and a stable interval is evidence for that interval. Neither is a referendum on every future policy.","流程图把校准放在进入前、实体输出准备放在执行前、观察放在接受前。配置变更须重查，旧运行仍是旧运行。安全停止是该条件下的失败，稳定时段是该时段证据，两者都不是关于未来所有政策的公投。")])
material("R4-Q404-R-TOWER","棱镜塔当前降载与安全检查","Q-404","mission_document","R4-S08.safety","r4-prism-current-duty-protocol",[
("The present tower duty has four declared local load units. Two are essential protection, one is public calibration service and one is a deferrable demonstration. Preserve the two protection units while reducing the demonstration load to zero; the calibration service may remain at one or be deferred with a recorded handover. This bounded current-duty reduction is separate from the laboratory load scale. Do not turn the tower off merely because a small controller was stable.","塔当前班负荷四个本地单位：两个必需保护、一个公共校准服务、一个可延后展示。保留两保护单位，把展示降至零；校准可留一或有记录交接后延后。此当前班降载与实验负荷尺度不同，不能因小控制器稳定就关闭塔。"),
("The duty officer will accept a specific current configuration. Inspect the protection return, secure the local isolation enclosure and physically verify the safe return stand. Record the readings after the chosen reduction, and repeat them if any load or connection changes. A proposal cannot reduce a live circuit. An old check cannot certify a new load. The result is current tower safety, not completion of a baseline or enhanced conversion.","值守员接受特定当前配置。检查保护回路、固定本地隔离围护，实际核查安全返程站。所选降载后记录读数，改负荷或连接须重查。提议不能降低现场回路，旧检查不能认证新负荷。结果是当前塔安全，不是基础或增强改造完成。"),
("The future work list requires one base isolator, one local backup and two base provisions, with two operator posts and installation capacity one. Enhanced preparation additionally lists one controller, two couplers, three transition crates and one trial fixture. Those are requirements rather than delivered stock. Do not borrow the laboratory's installed fixture into the account. Actual reservation, transport, delivery, installation, operation and agreement remain separate work.","未来清单需一基础隔离件、一地方备用、二基础供给、两值守岗位及一安装容量。增强再需一控制器、二耦合件、三过渡箱、一试验器材。它们是需求，不是已交库存，不能把实验室已装器材借进账。预留、运输、交付、安装、操作和协议仍分别执行。")],["4 duty units2essential1calibration1demo local candidate; base/enhanced lists lockedpart07 not granted"])
material("R4-Q404-R-ACCESS","扣押地点索引的限定调阅","Q-404","short_notice","R4-S04.facility","r4-facility-custodian-bounded-scope",[
("After the bounded technical trial is delivered, the records custodian can permit a separate review of the holding-facility index. Request facility code, supply destination, watch post and source version for the purpose of verifying the holding facility. The receiving patrol technician must keep the review at that level. Permission for report GH-R7 did not already include these records.","有限技术试验交接后，保管人可另准扣押设施索引查验。为核验扣押地点申请设施代号、供给目的地、看守岗位与来源版本，接收巡灯技术员保留此范围。GH-R7报告许可并未自动包含这些记录。"),
("Medical status, private addresses and the complete personal identity key remain excluded. This review can establish a place for the next lawful inquiry; it does not authorise a rescue as completed or establish a detainee's present condition. Preserve the three source references separately.","医疗状态、住址与完整身份键仍排除。此查验可为下一合法调查确定地点，未把救援授权为已完成，也未证明被扣者现状。三来源索引分别保留。")])
material("R4-Q404-R-LOCATION","设施代号与用途索引","Q-404","short_notice","R4-S04.facility","r4-facility-original-index",[
("The retained facility index maps custody code F-17 to the north-station holding facility in the old city. The code appears on the dated transfer reference already used in the priory investigation. This index provides a location mapping, not a new examination of the transferred person. Compare it with the supply destination and guard register before entering a location finding.","留存设施索引把扣押代码F-17对应旧都北站扣押设施。代码曾出现于修院已查日期转移索引。此索引提供地点映射，没有对被转移者做新检查。应与物资目的地和看守册比较后形成地点核验。"),
("This record does not disclose Mara's current medical condition or establish her present life status. It identifies a place for a lawful investigation. Unrelated personal fields are excluded from the public finding. The original design's historical responsibilities remain for their own later evidence review.","此记录不公开玛拉当前医疗情况，也没有证明目前生死，只提供合法查验地点。公共核查排除无关私人字段。原始设计的历史责任留待其后相应证据核验。")],["F17 alias continuity local candidate only; no prematureK-MARA-DESIGN-LIMIT"],access="controlled_review")
material("R4-Q404-R-SUPPLY","北站物资去向登记","Q-404","short_notice","R4-S04.supply_index","r4-north-station-supply-custody-original",[
("The supply register uses destination F-17 and names the old-city north station as the receiving facility. It records custody provision for that destination, separate from the laboratory's local trial materials. The delivery clerk kept this record independently of the facility index. Check the code and receiving-place fields; a delivery reference does not tell us a detainee's current condition.","物资册以F-17为目的地，接收设施写旧都北站，记录该处扣押保障供给，与实验室本地材料分账。交付员独立于设施索引保留此册。应查代码及接收地点；供给索引不说明被扣者当前情况。"),
("The public location summary may name the facility and the record versions. It must not attach unrelated personal addresses or present the shipment as a direct witness of Mara today. The next district will still require actual access, on-site inquiry and rescue work.","公开地点摘要可注明设施和记录版本，不能附无关住址，也不能把货运写成今日亲见玛拉。下一区仍需实际进入、现场查验与救援。")],access="controlled_review")
material("R4-Q404-R-GUARD","F-17看守配置核查页","Q-404","short_notice","R4-S04.guard_index","r4-north-station-watch-register-original",[
("The watch register places the custody post for code F-17 at the old-city north station. Its post and location fields are retained for verification. The record was kept by the custody office, separately from the supply clerk's delivery book. It supports the facility mapping alongside those other sources. It is a duty record, not a current interview with the held person.","看守册把F-17扣押岗位列在旧都北站，保留岗位及地点供核验。扣押办公室独立于供给交付册保存此记录，与其他来源共同支持设施映射。它是岗位记录，不是与被扣者的当前面谈。"),
("Keep the finding at the location level until the next investigation has direct access. Knowing where a facility is does not authorise its rescue in advance, make a returned person appear here, or settle the designer's historical part in the network. Follow the next commission through actual travel and legal entry.","下一查验直接进入前，把核查限于地点。知道设施位置不会提前完成救援，不会令被接回者出现在这里，也没有裁定设计者历史作用。下一委托仍需实际旅行与合法进入。")],access="controlled_review")
material("R4-Q404-R-PREPARATION","公开转型准备清单","Q-404","mission_document","R4-S08.preparation","r4-six-tower-preparation-public-list",[
("The bounded island result makes a wider proposal worth preparing; it does not complete that preparation. A distributed route requires the verified scheme, actual six-tower changes, transition supplies, a common protocol and on-site trial receipts. Each item has a current owner, version and completion condition. These conditions are public now. They will not be introduced later as a hidden optional story requirement.","有限孤网结果使广泛方案值得准备，没有完成准备。分布式路线需验证方案、实际六塔改造、过渡供给、共同协议和现场试运行回执，各有当前权威、版本及完成条件。条件现在公开，不会日后变成隐藏可选剧情要求。"),
("Base protection is also required whichever final route is chosen. A promise of autonomy cannot create goods or a trained shift. Central coordination may provide real help, and keeping it does not clear officials of responsibility for suppressed evidence. District operators and representatives accept their own actual clauses. A laboratory technician cannot sign for every region, and five organisations are not six district signatures.","无论终局路线，基础保护都需成立。自治承诺造不出货物或受训班次，中央协调确有作用，保留中央也不会抹去压制证据责任。地区操作方与代表确认本地实际条款，实验技术员不能代签各区，五组织不等于六地区签字。"),
("Work orders will show available sources, reservations, transport, delivery, installation and tests separately. The current Prism safety receipt records only this tower's reduction and checks. Future work remains pending until actual steps produce their receipts. Personal parts, trial modules and engineering cargo have separate accounts; no wording choice or writing score multiplies supplies.","工作单分别显示来源、预留、运输、交付、安装和测试。当前棱镜安全回执只记录本塔降载与检查，未来步骤尚待实际回执。个人零件、实验模块及工程货分别记账，措辞选择或写作分数不会倍增物资。")])
material("R4-Q404-L-VOSS","沃斯：供给与复核交涉脚本","Q-404","listening_script","R4-S02.voss","r4-voss-first-complete-exchange",[
("Voss: I knew that sustained high load carried a long-term risk. Your retained failures must be part of the discussion. I still require a plan for the first week: who maintains protection, where the transition supply comes from, and who accepts responsibility between districts. A ten-minute local result cannot supply those fields. I propose delaying public release while the central system continues to coordinate.","沃斯：我知道持续高负荷有长期风险，你保留的失败必须进入讨论。但第一周仍需计划：谁维护保护、过渡供给来自哪里、各区之间谁承责。十分钟本地结果填不出这些字段。我主张延后公开，同时由中央继续协调。"),
("Sian: Supply concerns are real, but they do not justify removing unfavourable results or denying an independent review. We can record the limits and practical preparation while retaining public scrutiny. You may agree with a technical concern and refuse the proposed information restriction. Those decisions are separate. The location records should also pass through their bounded verification; a holding-facility code does not tell us Mara's present condition.","西安：供给担忧确实存在，但不能据此删除不利结果或拒绝独立复核。可以记录限制及实际准备，同时保留公共查验。你可赞同技术担忧并拒绝信息限制，两决定分别保存。地点记录也按限定范围核验；扣押设施代码不说明玛拉目前情况。")],["Voss knowledge attribution Q404 not earlyK-VOSS-AUTHORIZATION E09"])
material("R4-Q404-R-ESSAY","十分钟之后：供给、证据与可复核方案","Q-404","extended_reading","R4-S03.policy_essay","r4-sian-technical-options-essay",[
("A useful technical proposal must be able to survive an inconvenient observation. If the only saved results are the two stable runs, a reader may mistake repetition for a guarantee. The retained Controller A sheet makes a narrower statement: load 40 with reserve was stable during two ten-minute windows; higher load with reserve stopped, and load 40 without reserve stopped. Those failures belong in the account. They describe limits worth investigating, rather than embarrassing pages to be removed. A later working arrangement does not make the earlier machine behave differently in the past.","可用方案应经受不利观察。只存两稳定记录，会让读者把重复误作保证。A控制器留存页范围较窄：40有储备两次十分钟稳定；较高负荷有储备停止，40无储备也停止。失败须保留，说明值得查验的边界，并非应删尴尬页。后来可用安排不会改变过去机器行为。"),
("The independent field curves and the controller records answer related but different questions. Survey teams observed a pattern across places. Their locations differ in ground conditions, previous operation and available supply. A laboratory run holds a smaller set of declared conditions and permits a specific comparison. Neither dataset alone contains every cause. Combining them responsibly means naming their source roots and scopes, not adding copies until a claim appears certain. An issued report and its retained manuscript may expose a publication difference while still referring to the same original trial.","独立现场曲线与控制器回答相关而不同问题。调查跨地点看模式，地层、运行历史和供给不同；实验固定较小一组声明条件，可做特定比较。两者均未含全部原因。负责任的结合要注明来源根和范围，不能多添副本便显得确定。发行与留存稿可证明呈现差异，仍指同一原试验。"),
("Controller C adds a practical test of the proposed alternative. Its local circuit operates at a finite load, with checked isolation, reserve, limited contact and assigned duty. The execution machine is first made safe and its output physically returned through the test route. Observations at five and ten minutes then record that arrangement. This sequence matters: a configured console is not a running circuit, and controlling an enemy device does not measure the trial output. The accepted interval belongs to the current revision. Changing a connector requires another check even if the earlier run remains a valid historical observation.","C增加替代方案实体核验：有限负荷、受检隔离、储备、有限联络与岗位。先制止执行机，将输出实际送回测试环，再以五及十分钟观察记录安排。顺序重要：控制台配置不是运行回路，制止敌装置没有测实验输出。接受时段属于当前版本；改连接须重查，即使早运行仍是有效历史观察。"),
("The statement that an interval was stable is useful without being universal. It does not settle load 55, a scale absent from the validated set, or permanent six-tower service. A refusal to invent a reading is an honest limit of the apparatus, not an assertion that the missing condition would certainly fail. Similarly, a high-load safe stop does not imply that every local arrangement is impossible. A careful report preserves supported, contradicted and untested claims separately. It can recommend a bounded next step while leaving a larger question open.","稳定时段有用，无需普遍化。它没有裁定验证集合未含的55，也没有证明六塔永久供给。拒绝编读数是器材诚实边界，不是断言未测条件必败；高负荷停止也不表示一切本地安排不可能。报告分别保留支持、矛盾和未测主张，可推荐有限下一步并开放较广问题。"),
("Reducing excess extraction is therefore necessary work, but it does not promise an immediate clear sky. The mist existed before the present overloading, and past damage does not vanish when a selector moves. Essential protection and genuine cross-region help still matter. The Prism duty sheet separates protection, calibration service and a deferrable display. Preserving protection while reducing an unnecessary load is a current safety action. It does not transfer the tower into a permanent local scheme or deliver future equipment. Its result should be recorded alongside the trial rather than confused with it.","降低超额抽取需做，却不承诺立刻晴空。雾原已存在，选择器一动不会抹去过去损伤。必需保护及真实跨区互助仍重要。棱镜班表分保护、校准和可延展示，保保护并降非必需负荷是当前安全行动，没有把塔转成永久本地方案，也未交未来设备。其结果与试验并列，不能混同。"),
("Voss's questions about a transition week deserve specific answers. Goods need a source and a destination, duties need people and a handover, and a common protocol needs the actual participants' acceptance. These requirements can be examined without accepting her request to delay independent scrutiny. Agreement with a concern is not agreement with every measure proposed in its name. Retain the unfavourable appendix and the limits of the new result. The choice to keep central coordination later will not erase a person's documented responsibility; a preference for distribution will not create a missing spare or excuse an unsafe operation.","沃斯关于过渡周的问题需具体答：货物有来源与去处，岗位有人员与交接，共同协议需实际参与者接受。查这些条件不必接受延后独立复核。赞同担忧不等于赞同以其名义所有措施。保留不利附录及新结果边界，日后保留中央不会抹去已记录责任，偏好分布也不会生成零件或使危险操作免责。"),
("The public preparation list puts those obligations within reach before the final decision. It names the verified scheme, six-tower changes, transition supply, common protocol and field trial. Each district can show actual progress, and an unfinished item stays unfinished. This is preferable to discovering a hidden requirement after a long journey. A report can compare options without choosing the final policy today. It should distinguish what has been achieved here, what needs work elsewhere and what the sources cannot yet tell us. That distinction gives the next investigator something useful to test rather than another promise to repeat.","公开清单在终局前把义务摆明：方案、六塔改造、过渡供给、共同协议、现场试运行。各区显示实际进度，未完成保持未完成，胜于旅程末才发现隐藏要求。报告可比较方案而不今日定终局，区分本地已做、外区待做、来源尚不能告知之处，使下一查验有可检验事项，而非另一承诺。")])
material("R4-CQMIRA02-R-REQUEST","审阅请求：只要角色数量","CQ-MIRA-02","short_notice","R4-S03.review_request","r4-mira-role-count-review-request",[
("The review desk requests counts by recorded duty role and the source version for the W-04 note group. It does not request personal names, private addresses or the complete identity key. Mira offers to help check the scope after the public technical report is delivered and the earlier W-04 handover is complete. Formal recruitment is not a condition. Accepting the invitation is separate from taking a private original out of custody.","复核台请求W-04笔记组按记录职务的数量及来源版本，未请求姓名、住址或完整身份键。公共技术报告及早W-04交接完成后，米拉可协助查范围；不要求正式招募。接受邀请与把私人原件移出保管是不同事。"),
("The retained group has three duty entries: two observer roles and one service role. The source identity key remains sealed. Prepare a derived review copy with those counts and its original source reference, then deliver it to this desk for this purpose. The copy is not an independent witness. If a later recipient asks for identities, seek each person's applicable permission; this request has not granted it.","保留组有三职务条目：两观察岗位、一服务岗位，来源身份键仍封存。应制角色数量及原来源索引的审阅副本，再为此用途交此台。副本不是独立见证；后来接收方请求身份，须取得每人适用许可，本请求没有授予。")],["3duty entries2observers1service original bounded privacy candidate; sealed identity values never authored into learner包"])
material("R4-O01-R-NOTICES","学生工作室：课程冲突通知","R4-OPTIONAL-STUDY","mission_document","R4-O01.notices","r4-student-course-notices",[
("The shared study room has two course notices for the same afternoon. The original notice places instrument practice in room Cedar at 14:00. A dated correction moves that practice to room Birch at 14:00 because Cedar is reserved for the archive workshop. Keep both notices, identify what the correction changes and ask the course desk for clarification if you intend to attend both. The correction concerns a room, not cancellation of a course.","共学室有同日下午两课程通知。原通知仪表练习14:00在Cedar，标日期更正改为14:00在Birch，因为Cedar留给档案工作坊。应保留两件，说明更正哪项，想参加两课则向课程台澄清。更正的是房间，不是取消课程。"),
("Write a formal inquiry that names the two notices, the relevant time and the question you need answered. You may save it before deciding whether to send. This local activity is about ordinary study arrangements. It does not hide a network order or supply an essential ending condition. Its independent optional contract and reward remain to be approved; saving an inquiry alone will not issue a completion receipt.","正式询问信注明两通知、相关时间与待答问题，可先保存再决定交付。这是普通学习安排，未藏网络命令或必需结局条件。独立可选合同及奖励待核定，存询问本身不出完成回执。")],["Cedar/Birch14:00 local ordinary-course candidate; no fixedcontract guessed"])
material("R4-O02-R-CONTRIBUTION","展签与贡献记录","R4-OPTIONAL-CREDIT","mission_document","R4-O02.label","r4-exhibition-contribution-records",[
("The display label credits the instrument housing to the workshop team and lists one presenter. The contribution book distinguishes construction, calibration and presentation: the workshop built the housing, two students checked reference marks, and the presenter explained the result. The presenter's speaking role is not evidence that the other work was absent. A revised label can name contributions without inventing additional people or changing the trial output.","展签将仪表外壳归工坊团队，列一介绍人。贡献簿分建造、校准与介绍：工坊制外壳，两学生查参考标，介绍人说明结果。发言角色不证明其他工作没有发生。修订展签可注明贡献，无需新造人或改试验输出。"),
("Compare the retained book with the proposed wording before suggesting a revision. Unverified claims may remain questions for the organiser. This display activity is not a trial-safety approval or a reward source for copying the main report. The independent optional contract, delivery recipient and budget allocation are still pending. The original label and your saved proposal remain available together.","提出修订前，比留存簿与拟用文字。未经核验主张可留给组织者作问题。展示活动不是试验安全批准，也不是复制主报告领奖来源。独立可选合同、接收方和预算分配仍待完成，原签及已存提议一起保留。")],["local credit-role distinction; no unique historical人物责任 invented"])

